/* Service worker: makes the app work fully offline.
 * precache.js (generated by `npm run build`) lists every app file and a version hash; a new hash installs a
 * new cache and removes the old one. User data is NOT touched here: it lives in IndexedDB. */
importScripts("precache.js");
const CACHE = `dnd-tracker-${self.__PRECACHE.version}`;

self.addEventListener("install", (event) => {
  // cache: "reload" skips the browser's HTTP cache, so a new version never mixes in stale files
  // (GitHub Pages lets browsers cache files for ~10 minutes).
  const requests = self.__PRECACHE.files.map((f) => new Request(f, { cache: "reload" }));
  event.waitUntil(caches.open(CACHE).then((c) => c.addAll(requests)).then(() => self.skipWaiting()));
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith("dnd-tracker-") && k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim()));
});

self.addEventListener("fetch", (event) => {
  const req = event.request;
  if (req.method !== "GET" || new URL(req.url).origin !== self.location.origin) return;
  event.respondWith((async () => {
    const cache = await caches.open(CACHE);
    // Any navigation (home-screen launch, reload) gets the app shell; routing happens client-side via the hash.
    const hit = await cache.match(req.mode === "navigate" ? "index.html" : req, { ignoreSearch: true });
    if (hit) return hit;
    try { return await fetch(req); }
    catch { return req.mode === "navigate" ? (await cache.match("index.html")) : Response.error(); }
  })());
});
